import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import productService from "../services/productService";
import AOS from "aos";
import "aos/dist/aos.css";
import "./ProductDetail.css";

function ProductDetail() {
    const { id } = useParams();

    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [quantity, setQuantity] = useState(1);

    useEffect(() => {
        AOS.init({
            duration: 1000,
            once: true,
            offset: 100,
            easing: "ease-in-out",
        });

        loadProductDetail();

        window.scrollTo({
            top: 0,
            behavior: "smooth",
        });
    }, [id]);

    const loadProductDetail = async () => {
        try {
            setLoading(true);

            const response = await productService.getProductById(id);
            const productData = response.data || response;

            setProduct(productData);

            setTimeout(() => {
                AOS.refresh();
            }, 100);
        } catch (error) {
            console.error("Lỗi khi tải chi tiết sản phẩm:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleQuantityChange = (type) => {
        if (type === "decrease" && quantity > 1) {
            setQuantity(quantity - 1);
        }

        if (type === "increase") {
            setQuantity(quantity + 1);
        }
    };

    if (loading) {
        return (
            <div className="detail-loading">
                <div className="spinner"></div>
                <p>Đang tải thông tin sản phẩm...</p>
            </div>
        );
    }

    if (!product) {
        return (
            <div className="detail-error">
                <h2>Không tìm thấy sản phẩm!</h2>

                <Link to="/shop" className="btn-back">
                    Quay lại cửa hàng
                </Link>
            </div>
        );
    }
   return (
        <div className="product-detail-page">
            <div className="container">

                {/* 1. THANH ĐIỀU HƯỚNG BREADCRUMB (NẰM TRÊN CÙNG) */}
                <div className="breadcrumb" data-aos="fade-down">
                    <Link to="/">Trang chủ</Link>
                    <span>/</span>
                    <Link to="/shop">Sản phẩm</Link>
                    <span>/</span>
                    <strong>{product.name}</strong>
                </div>

                {/* 2. BỐ CỤC HÀNG NGANG CHÍNH (CHỈ CHỦ ĐẠO 2 CỘT LỚN) */}
                <div className="detail-main-layout">

                    {/* CỘT TRÁI: HOÀN TOÀN CHỈ CHỨA ẢNH */}
                    <div className="layout-left-column" data-aos="fade-right">
                        <div className="product-badge">SMART FURNITURE</div>
                        <div className="product-image-box">
                            <img
                                src={product.imageUrl || "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85"}
                                alt={product.name}
                                className="product-image-element"
                                onError={(e) => {
                                    e.target.onerror = null;
                                    e.target.src = "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85";
                                }}
                            />
                        </div>
                    </div>

                    {/* CỘT PHẢI: CHỨA TOÀN BỘ NỘI DUNG CHỮ NỐI TIẾP NHAU */}
                    <div className="layout-right-column" data-aos="fade-left">
                        
                        {/* Khối thông tin mua hàng */}
                        <div className="info-card-section">
                            <h1 className="product-title">{product.name}</h1>

                            <div className="rating-row">
                                <span className="stars">⭐⭐⭐⭐•</span>
                                <span className="review-count">(25 đánh giá)</span>
                            </div>

                            <div className="product-price-box">
                                <span className="product-price">
                                    {typeof product.price === "number"
                                        ? product.price.toLocaleString("vi-VN", { style: "currency", currency: "VND" })
                                        : product.price}
                                </span>
                            </div>

                            <p className="product-short-description">
                                {product.shortDescription || "Thiết kế tinh tế, chất liệu cao cấp mang lại không gian sống hiện đại và đẳng cấp cho ngôi nhà của bạn."}
                            </p>

                            {/* Đặc điểm */}
                            <div className="feature-list">
                                <div className="feature-item">✓ Thiết kế hiện đại</div>
                                <div className="feature-item">✓ Chất liệu cao cấp</div>
                                <div className="feature-item">✓ Bảo hành chính hãng</div>
                                <div className="feature-item">✓ Giao hàng toàn quốc</div>
                            </div>

                            {/* Tương tác đặt hàng */}
                            <div className="purchase-action-group">
                                <div className="quantity-selector">
                                    <button type="button" onClick={() => handleQuantityChange("decrease")}>−</button>
                                    <input type="number" value={quantity} readOnly />
                                    <button type="button" onClick={() => handleQuantityChange("increase")}>+</button>
                                </div>

                                <button type="button" className="btn-add-to-cart">
                                    🛒 Thêm vào giỏ hàng
                                </button>
                            </div>

                            {/* Metadata */}
                            <div className="product-meta">
                                <p><strong>Tình trạng:</strong> <span className="stock-status">Còn hàng</span></p>
                                <p><strong>Mã sản phẩm:</strong> SKU-{product.id}</p>
                                <p><strong>Danh mục:</strong> Nội thất thông minh</p>
                            </div>
                        </div>

                        {/* Khối mô tả chi tiết sản phẩm nối tiếp ở dưới */}
                        <div className="product-tabs-section">
                            <div className="tab-header">
                                <h3>Mô tả chi tiết sản phẩm</h3>
                            </div>
                            <div className="tab-content">
                                <p>{product.description || "Chưa có mô tả chi tiết cho sản phẩm này."}</p>
                            </div>
                        </div>

                        {/* Khối sản phẩm liên quan dưới cùng của cột phải */}
                        <div className="related-products">
                            <div className="section-title">
                                <h2>Sản phẩm liên quan</h2>
                            </div>
                            <div className="related-placeholder">
                                <p>Các sản phẩm liên quan sẽ hiển thị tại đây.</p>
                            </div>
                        </div>

                    </div> {/* KẾT THÚC layout-right-column */}

                </div> {/* KẾT THÚC detail-main-layout */}

            </div>
        </div>
    );
}

export default ProductDetail;
